it('wraps a string rejection for onError while preserving the caller rejection', async () => {
  const rejection = 'string boom';
  let receivedError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      receivedError = error;
    },
  };
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw rejection;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {
    sessionId: 'test-session',
    userId: 'user-1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const orchestrator = createChatOrchestrator(
    provider,
    new PromptBuilder({identity: 'You are a test assistant.'}),
    undefined,
    {hooks}
  );

  const thrown = await orchestrator.processMessage(session).catch(error => error);

  expect({
    thrown,
    isError: receivedError instanceof Error,
    message: receivedError?.message,
    cause: receivedError?.cause,
  }).toEqual({thrown: rejection, isError: true, message: rejection, cause: rejection});
});

